<script setup>
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { adminOrders, pendingRefunds, reviewRefund, shipOrder } from '../../api/admin'
import PageTitle from '../../components/PageTitle.vue'
const rows=ref([]),loading=ref(false),current=ref(1),total=ref(0),refunds=ref([]),refundPage=ref(1),refundTotal=ref(0),status=ref(''),orderNo=ref(''),userId=ref(''),carrier=ref(''),trackingNo=ref('')
async function load(){loading.value=true;try{const p=await adminOrders({current:current.value,size:10,status:status.value===''?undefined:Number(status.value),orderNo:orderNo.value||undefined,userId:userId.value?Number(userId.value):undefined});rows.value=p?.records||[];total.value=Number(p?.total||0)}finally{loading.value=false}}
async function loadRefunds(){const p=await pendingRefunds({current:refundPage.value,size:10});refunds.value=p?.records||[];refundTotal.value=Number(p?.total||0)}
async function review(row,approved){let auditRemark='';if(!approved){const value=window.prompt('请填写拒绝原因');if(!value?.trim())return;auditRemark=value}else auditRemark=window.prompt('审核备注（选填）')||'';await reviewRefund(row.id,{approved,auditRemark});ElMessage.success('退款申请已审核');loadRefunds()}
async function ship(row){const no=row.orderNo;const {value}=await ElMessageBox.prompt(`为订单 ${no} 登记物流公司和单号，以逗号分隔`,'订单发货',{inputValue:''});const [c,t]=(value||'').split(',').map(x=>x.trim());if(!c||!t)return ElMessage.warning('请按“物流公司,物流单号”填写');await shipOrder(no,{carrier:c,trackingNo:t});ElMessage.success('已登记发货');load()}
onMounted(()=>{load();loadRefunds()})
</script>
<template><div class="admin-page"><PageTitle eyebrow="FULFILLMENT" title="订单与退款" description="订单列表只读；发货及退款审核调用后端现有管理接口。"/><section class="content-card"><div class="toolbar"><el-input v-model="orderNo" placeholder="订单号" clearable/><el-input v-model="userId" placeholder="用户 ID" clearable/><el-select v-model="status" placeholder="全部状态" clearable><el-option label="待支付" value="0"/><el-option label="已支付" value="1"/><el-option label="已完成" value="2"/><el-option label="已取消" value="3"/><el-option label="已发货" value="4"/><el-option label="已退款" value="5"/></el-select><el-button type="primary" @click="current=1;load()">筛选</el-button></div><el-table v-loading="loading" :data="rows"><el-table-column prop="orderNo" label="订单号" min-width="190"/><el-table-column prop="username" label="用户名" width="120"/><el-table-column prop="albumTitle" label="商品" min-width="160"/><el-table-column prop="totalAmount" label="金额" width="100"/><el-table-column prop="statusText" label="状态" width="100"/><el-table-column prop="createTime" label="创建时间" min-width="170"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="Number(row.status)===1&&row.productType==='PHYSICAL'" text type="primary" @click="ship(row)">登记发货</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="current" :page-size="10" :total="total" layout="prev,pager,next" @current-change="load"/></div></section><section class="content-card"><h2>待审核退款</h2><el-table :data="refunds"><el-table-column prop="id" label="申请 ID" width="90"/><el-table-column prop="orderNo" label="订单号" min-width="180"/><el-table-column prop="reason" label="原因"/><el-table-column prop="description" label="说明"/><el-table-column label="操作" width="170"><template #default="{row}"><el-button type="success" text @click="review(row,true)">通过</el-button><el-button type="danger" text @click="review(row,false)">拒绝</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="refundPage" :page-size="10" :total="refundTotal" layout="prev,pager,next" @current-change="loadRefunds"/></div></section></div></template>

